#include "cinderwatch/rules/rules.h"
namespace cinderwatch::rules{using namespace core;static bool allow(const std::string&a){auto x=lower(a);return x=="accept"||x=="allow";}static bool block(const std::string&a){auto x=lower(a);return x=="drop"||x=="reject"||x=="deny";}static bool broad(const FirewallRule&r){return !r.has_src&&!r.has_dst&&!r.has_dport&&(r.proto=="any"||r.proto.empty());}Result<FirewallRule> parse_iptables(const std::string&l,size_t n){auto ts=shell_tokens(l,n);FirewallRule r;r.raw=l;r.style="iptables";r.line=n;for(size_t i=0;i<ts.size();++i){auto t=ts[i].text;auto nx=[&](){return i+1<ts.size()?ts[++i].text:"";};if(t=="iptables")continue;else if(t=="-A"||t=="-I"||t=="-P")r.chain=nx();else if(t=="-t")r.table=nx();else if(t=="-p")r.proto=lower(nx());else if(t=="-s"){auto c=parse_cidr(nx());if(!c)return c.st;r.src=c.value();r.has_src=true;}else if(t=="-d"){auto c=parse_cidr(nx());if(!c)return c.st;r.dst=c.value();r.has_dst=true;}else if(t=="--sport"){auto p=parse_port_range(nx());if(!p)return p.st;r.sport=p.value();r.has_sport=true;}else if(t=="--dport"){auto p=parse_port_range(nx());if(!p)return p.st;r.dport=p.value();r.has_dport=true;}else if(t=="-i")r.inif=nx();else if(t=="-o")r.outif=nx();else if(t=="-j")r.action=lower(nx());else if(t=="--state"||t=="--ctstate")r.state=lower(nx());else if(t=="--comment")r.comment=nx();}if(r.chain.empty())r.chain="INPUT";if(r.action.empty())r.action="accept";return r;}Result<FirewallRule> parse_nft(const std::string&l,size_t n){auto ts=shell_tokens(l,n);FirewallRule r;r.raw=l;r.style="nftables";r.line=n;r.chain="input";for(size_t i=0;i<ts.size();++i){auto t=lower(ts[i].text);auto val=[&](size_t k){return i+k<ts.size()?ts[i+k].text:"";};if(t=="chain")r.chain=val(1);else if(t=="ip"&&lower(val(1))=="saddr"){auto c=parse_cidr(val(2));if(!c)return c.st;r.src=c.value();r.has_src=true;i+=2;}else if(t=="ip"&&lower(val(1))=="daddr"){auto c=parse_cidr(val(2));if(!c)return c.st;r.dst=c.value();r.has_dst=true;i+=2;}else if((t=="tcp"||t=="udp")&&lower(val(1))=="dport"){r.proto=t;auto p=parse_port_range(val(2));if(!p)return p.st;r.dport=p.value();r.has_dport=true;i+=2;}else if(t=="accept"||t=="drop"||t=="reject")r.action=t;}if(r.action.empty())r.action="accept";return r;}FirewallSet parse_firewall(const std::string&t){FirewallSet s;size_t n=0;for(auto&l:lines(t)){n++;auto x=trim(l);if(x.empty()||x[0]=='#')continue;auto r=starts(x,"-")||starts(x,"iptables")?parse_iptables(x,n):parse_nft(x,n);if(r)s.rules.push_back(r.value());else s.diagnostics.push_back({Severity::Medium,"firewall.parse",r.st.msg,{"",n,1,r.st.off}});}return s;}static std::string key(const FirewallRule&r){std::ostringstream o;o<<r.table<<r.chain<<r.proto<<(r.has_src?r.src.text():"any")<<(r.has_dst?r.dst.text():"any")<<(r.has_dport?r.dport.text():"any")<<r.action;return o.str();}static bool covers(const FirewallRule&a,const FirewallRule&b){if(a.chain!=b.chain)return false;if(a.proto!="any"&&a.proto!=b.proto)return false;if(a.has_src&&(!b.has_src||!a.src.contains(b.src.net)))return false;if(a.has_dst&&(!b.has_dst||!a.dst.contains(b.dst.net)))return false;if(a.has_dport&&(!b.has_dport||!a.dport.contains(b.dport.a)||!a.dport.contains(b.dport.b)))return false;return true;}Report validate_firewall(const FirewallSet&s){Report r;r.subject="Firewall validation";r.diagnostics=s.diagnostics;std::set<std::string>seen;bool deny=false;for(size_t i=0;i<s.rules.size();++i){auto&x=s.rules[i];if(!seen.insert(key(x)).second)r.findings.push_back({Severity::Medium,"firewall","Duplicate rule","Rule duplicates an earlier rule",{"",x.line,1,0},{x.raw}});if((x.chain=="INPUT"||x.chain=="input")&&block(x.action)&&broad(x))deny=true;if(allow(x.action)&&broad(x))r.findings.push_back({Severity::High,"firewall","Broad allow rule","Rule allows broad traffic",{"",x.line,1,0},{x.raw}});for(size_t j=0;j<i;j++)if(covers(s.rules[j],x)){r.findings.push_back({allow(s.rules[j].action)==allow(x.action)?Severity::Medium:Severity::High,"firewall","Shadowed rule","Earlier rule covers this rule",{"",x.line,1,0},{s.rules[j].raw,x.raw}});break;}}if(!deny)r.findings.push_back({Severity::Medium,"firewall","Missing default deny indicator","No broad inbound deny posture was detected"});return r;}std::string firewall_text(const FirewallSet&s,const Report&r){std::ostringstream o;o<<"Firewall rules parsed: "<<s.rules.size()<<"\n"<<report_text(r);return o.str();}std::string firewall_json(const FirewallSet&s,const Report&r){return std::string("{\"rules\":")+std::to_string(s.rules.size())+",\"report\":"+report_json(r)+"}";}}
